const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Shebelle River in Somalia (approximate point along the river)
  const riverPoint = ee.Geometry.Point([45.0, 2.0]);
  const roi = riverPoint.buffer(10000); // 10km buffer

  // Date ranges (exact dates with small buffer)
  const date1Start = '2015-05-16';
  const date1End = '2015-05-18';
  const date2Start = '2018-05-08';
  const date2End = '2018-05-10';

  // 2. Data Acquisition - Use Sentinel-1 for water detection (cloud-agnostic)
  const getCollection = (startDate, endDate) => {
    return ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select('VV')
      .filter(ee.Filter.eq('instrumentMode', 'IW')); // Standard imaging mode
  };

  const col1 = getCollection(date1Start, date1End);
  const col2 = getCollection(date2Start, date2End);

  // Check collection sizes
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`2015 Images: ${size1}, 2018 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    // Try Landsat 8 as backup for water index (but note: clouds may interfere)
    console.log("No Sentinel-1 data, trying Landsat 8...");
    const landsat1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date1Start, date1End)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const landsat2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date2Start, date2End)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const lsSize1 = landsat1.size().getInfo();
    const lsSize2 = landsat2.size().getInfo();
    console.log(`Landsat 2015: ${lsSize1}, Landsat 2018: ${lsSize2}`);

    if (lsSize1 === 0 || lsSize2 === 0) {
      console.log("<answer>C1</answer>");
      return;
    }

    // Use Landsat for MNDWI (water index)
    const calcMndwi = (img) => {
      const mndwi = img.normalizedDifference(['SR_B3', 'SR_B6']).rename('mndwi');
      return img.addBands(mndwi);
    };

    const img1 = landsat1.map(calcMndwi).median().select('mndwi');
    const img2 = landsat2.map(calcMndwi).median().select('mndwi');

    // Calculate water extent (MNDWI > 0 indicates water)
    const reducer = ee.Reducer.count();

    const stats1 = img1.gt(0).reduceRegion({
      reducer: reducer,
      geometry: roi,
      scale: 3000,
      maxPixels: 1e9
    });

    const stats2 = img2.gt(0).reduceRegion({
      reducer: reducer,
      geometry: roi,
      scale: 3000,
      maxPixels: 1e9
    });

    const waterPixels1 = stats1.get('mndwi').getInfo();
    const waterPixels2 = stats2.get('mndwi').getInfo();

    console.log(`2015 Water Pixels: ${waterPixels1}, 2018 Water Pixels: ${waterPixels2}`);

    if (waterPixels1 === null || waterPixels2 === null) {
      console.log("<answer>C3</answer>");
    } else if (waterPixels1 === 0 || waterPixels2 === 0) {
      console.log("<answer>C2</answer>");
    } else if (waterPixels2 > waterPixels1) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }
    return;
  }

  // 3. Process Sentinel-1 data
  // Lower VV values indicate water (typically < -15 dB for smooth water)
  const img1 = col1.mean().clip(roi);
  const img2 = col2.mean().clip(roi);

  // Count water pixels (VV < -15 dB)
  const waterThreshold = -15;
  const reducer = ee.Reducer.count();

  const stats1 = img1.lt(waterThreshold).reduceRegion({
    reducer: reducer,
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.lt(waterThreshold).reduceRegion({
    reducer: reducer,
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterPixels1 = stats1.get('VV').getInfo();
  const waterPixels2 = stats2.get('VV').getInfo();

  console.log(`2015 Water Pixels: ${waterPixels1}, 2018 Water Pixels: ${waterPixels2}`);

  // 4. Validation & Final Answer
  if (waterPixels1 === null || waterPixels2 === null) {
    console.log("<answer>C3</answer>");
  } else if (waterPixels1 === 0 || waterPixels2 === 0) {
    console.log("<answer>C2</answer>");
  } else if (waterPixels2 > waterPixels1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
